package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IngestKeyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property ingest key of observed source ")
  void test_ingest_key_v_o_builder() {
    Assertions.assertFalse(IngestKeyVO.nullValue().getIngestKey().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(IngestKeyVO.tryFrom(null).getIngestKey().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", IngestKeyVO.from("one").getIngestKey().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> IngestKeyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", IngestKeyVO.from("one").toString());
  }
}
